//web.pcc.gov.tw/prkms/tender/common/noticeDate/redirectPublic?ds=20261106&fn=BDM-1-71324442.xml", "date": "2026-11-06", "unit": "高雄市那瑪夏區公所", "category": "標案", "topic": "高雄市那瑪夏區公所", "summary": "高雄市那瑪夏區公所於2026-11-06在政府電子採購網刊登「決標公告」，標案名稱為「115年-116年公務車輛租賃財物採購案」，得標或投標廠商包括豪想出去玩租賃有限公司、小馬國際租賃股份有限公司。詳細預算金額、履約期限與投標資格請見原始公告。"}, {"title": "農試所於11月7日辦理「黃金泡菜製作教學課程體驗活動」歡迎民眾報名", "url": "https://www.kinmen.gov.tw/News_Content.aspx?n=1BC6B0D9638A6EE2&sms=A2C62D68901B977C&s=EC218EB34E1B66DF", "date": "2026-11-06", "unit": "金門縣政府", "category": "綜合新聞", "topic": "金門縣政府", "summary": "大白菜是金門冬季重要的作物，為十字花科蕓薹屬，二年生草本，喜涼冷氣候，大白菜由中國人培育產生，古時稱「菘」，至少從南北朝時起就是中國南方最常食用的蔬菜之一。富含有大量粗纖維，可促進腸壁蠕動，保持大便通暢。大白菜性味甘平，有清熱除煩、解渴利尿、通利腸胃的功效，經常吃大白菜(包心白菜)可防止維生素C缺乏症(壞血病)。"}, {"title": "115年臺南市動產擔保交易登記清冊", "url": "https://data.tainan.gov.tw/DataSet/Detail/d49a5e24-4697-4a28-b1df-83d2af8f06ea", "date": "2026-11-06", "unit": "臺南市政府", "category": "政策", "topic": "臺南市政府", "summary": "機關單位 : 臺南市政府經濟發展局 瀏覽次數: 3588 下載次數: 1522 下載流量統計(MB): 0 115年臺南市動產擔保交易登記清冊 CSV JSON 提供動產擔保交易登記清冊 標籤"}, {"title": "南市新增1境外移入個案，市長黃偉哲提醒出國旅遊防蚊措施要做足，返國有症狀速就醫勿延誤！", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13371&s=8845708", "date": "2026-11-06", "unit": "臺南市政府", "category": "政策", "topic": "臺南市政府", "summary": "南市11月6日新增1例登革熱境外移入病例，個案為永康區永康里40多歲本國籍女性，於10月28日至11月1日期間至越南員工旅遊，返國初期無不適症狀並前往高雄市工作地上班，11月4日起陸續出現發燒、頭痛及全身痠痛等症狀，11月5日至安南醫院就醫，醫師予以登革熱NS1快篩為陽性通報，經實驗室檢驗PCR陽性…"}, {"title": "全國託播 - 116年度「文化部扶植青年藝術發展補助」自115年11月5日受理申請", "url": "https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$5600&IDK=2&EXEC=D&DATA=77219&AP=$5600_HISTORY-0^$5600_PN-1", "date": "2026-11-06", "unit": "高雄市政府", "category": "補助", "topic": "高雄市政府", "summary": "一、為扶植協力具潛力之青年發展藝術創作，給予青年新秀藝術創作舞台及曝光機會，培養開拓青年參與藝術文化，文化部透過扶植青年藝術發展補助作業要點，落實青年文化平權，並建構藝文創作自由的支持體系，充分發展臺灣的原創力及文化力。"}, {"title": "竹田鄉公所-最新消息-【轉知】屏東縣政府檢送116年300億元中央擴大租金補貼專案計畫租金補貼受理申請公告1份。", "url": "https://www.pthg.gov.tw/townjtt/News_Content.aspx?n=09E3DC243E8C0D19&s=3790FEDE46AF2861", "date": "2026-11-05", "unit": "屏東縣政府", "category": "預算", "topic": "屏東縣政府", "summary": "最新消息 - 發佈日期：115-10-30 資料來源：竹田鄉公所 【轉知】屏東縣政府檢送116年300億元中央擴大租金補貼專案計畫租金補貼受理申請公告1份。"}, {"title": "黃偉哲受邀出席新光三越新天地寶可夢耶誕點燈 邀民眾遊台南、享美食、抽好禮", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8845492", "date": "2026-11-05", "unit": "臺南市政府", "category": "綜合新聞", "topic": "臺南市政府", "summary": "發稿單位：新聞及國際關係處 發稿時間：115年11月5日19:40 發稿人：林靜怡 台南歲末耶誕活動陸續登場，新光三越台南新天地今年攜手人氣IP「寶可夢」，打造期間限定「2026寶可夢耶誕樂園」，設置16米高主題耶誕樹及大型寶可夢裝置，營造節慶氛圍。"}, {"title": "115年10月份高雄市物價變動概況", "url": "https://bas.kcg.gov.tw/News_Content.aspx?n=DFA2E6E21E2F56AC&sms=210F1CD2DBBB0267&s=36B1F52A61DDB848", "date": "2026-11-05", "unit": "高雄市政府", "category": "綜合新聞", "topic": "高雄市政府", "summary": "新聞稿 - 資料更新時間：115-11-05 14:11 壹、消費者物價指數變動提要分析 115年10月份本市消費者物價總指數為112.70，較上月113.01下跌0.27％；另較上年同月110.69上漲1.82％。"}, {"title": "勞工領袖大學菁英班帶領學員掌握科技脈動與智慧製造新知", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13371&s=8845493", "date": "2026-11-05", "unit": "臺南市政府", "category": "政策", "topic": "臺南市政府", "summary": "為打造市長黃偉哲「希望家園」的施政願景、提升工會幹部及在職勞工管理職能與職場競爭力，臺南市政府勞工局與國立成功大學合作辦理｢勞工領袖大學菁英班」，今(5)日於成功大學成功校區小格致廳迎來壓軸課程。本場講座邀請到國立成功大學教務處推廣教育中心主任王郁仁，以「工業4.0與機器人發展」為題，帶領勞工幹部掌握產業界最前瞻的科技脈動與智慧製造新知。"}, {"title": "【代發社會局新聞稿】兒少保護不是開案越少越好高市府：強化風險辨識、落實追蹤服務，才能真正接住孩子", "url": "https://www.kcg.gov.tw/CityNews_Detail1.aspx?n=3A379BB94CA5F12D&ss=27F19D5F51061A4B", "date": "2026-11-05", "unit": "高雄市政府", "category": "政策", "topic": "高雄市政府", "summary": "兒少保護的重點不是追求開案數字降低，而是及早發現風險、積極介入服務，避免需要幫助的孩子被遺漏。社會局指出，中央推動強化社會安全網政策，就是透過社、衛、警、教育及醫療等跨專業合作，及早辨識風險、積極開案。兒少保護案件從疏忽照顧、兒童獨留家中，到嚴重虐待、保護安置甚至虐待致死，風險程度及處遇方式各不相同，不能將不同性質的案件混為一談，僅憑單一數字評斷兒少保護成效。"}, {"title": "繁花盛開迎新生 花蓮縣推出珍愛寶貝新生兒祝福禮2.0", "url": "https://www.hl.gov.tw/News_Content.aspx?n=32725&sms=25832&s=233585", "date": "2026-11-05", "unit": "花蓮縣政府", "category": "政策", "topic": "花蓮縣政府", "summary": "迎接新生命，是家庭幸福的開始，也是城市希望的延續。花蓮縣政府持續推動友善育兒政策，推出「珍愛寶貝新生兒祝福禮2.0」。凡出生並設籍花蓮縣的新生兒，家長至本縣戶政事務所辦理出生登記或初設戶籍登記後，即可現場領取新生兒祝福禮，傳遞縣府對每位新生命最誠摯的祝福。縣長徐榛蔚表示，孩子是家庭的希望，也是花蓮未來重要的力量。"}, {"title": "臺東縣政府行政處庶務科科員A030150職代1名", "url": "https://www.taitung.gov.tw/News_Content.aspx?n=13377&sms=12655&s=150506", "date": "2026-11-05", "unit": "臺東縣政府", "category": "政策", "topic": "臺東縣政府", "summary": "（一）符合資格且有意任職者，應徵方式如下（請擇一方式應徵即可）： 1. 請逕至本府人事處網站-表單下載 下載「公務人員簡式履歷表」，依式填寫基本資料（含照片）、自傳及相關工作經驗，並於公告結束日期前將電子檔寄至o10093@taitung.gov.tw…", "title_raw": "臺東縣政府行政處庶務科科員A030150職代1名"}, {"title": "臺南市南區樂齡學習數位示範體驗場域正式揭牌 開啟數位共融新生活", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13371&s=8845489", "date": "2026-11-05", "unit": "臺南市政府", "category": "政策", "topic": "臺南市政府", "summary": "為提升高齡者數位素養及資訊應用能力，縮短數位落差，臺南市政府教育局今年於南區喜樹國小建置教育部「樂齡學習數位示範體驗場域」，並於今(5)日舉行揭牌儀式，由教育部終身教育司司長梁學政、南市教育局副局長楊智雄等人共同主持，以「數位樂齡Cafe」正式亮相。場域以「高齡友善、數位共融、在地實踐」為理念，結合數位課程及諮詢服務，打造兼具學習、交流與生活應用的樂齡數位學習環境。"}, {"title": "智匯臺南、算力領航！ 黃偉哲宣布AI服務引擎啟動， AMD捐贈算力設備助攻智慧市政與在地創新", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13371&s=8845462", "date": "2026-11-05", "unit": "臺南市政府", "category": "政策", "topic": "臺南市政府", "summary": "臺南市政府今（5）日舉辦「智匯臺南・算力領航：AMD科技助攻 臺南市AI服務引擎啟動記者會」。配合中央「AI新十大建設推動方案」及「大南方新矽谷推動方案」，臺南以沙崙為樞紐，吸引AMD設立研發據點，並結合學研機構與產業聚落，逐步形成從技術研發、算力支援到場域驗證的AI創新生態系。"}, {"title": "臺南市長照專業服務成果發表會分享溫馨復能故事、見證長輩重拾自立", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13371&s=8845464", "date": "2026-11-05", "unit": "臺南市政府", "category": "政策", "topic": "臺南市政府", "summary": "「能自己穿衣、洗澡、拿湯匙，對長輩來說，每一點進步不僅是找回自信的重要一步，更是重新拿回生活的掌控權。」長照不只是生活起居的被動照料，更是協助長輩重新拿回自我照顧能力的重要支持。"}, {"title": "黃偉哲市長八年深耕社宅從無到有 臺南社宅量能突破1.2萬戶 市府攜手中央成效市民有感", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8844853", "date": "2026-11-05", "unit": "臺南市政府", "category": "政策", "topic": "臺南市政府", "summary": "發稿單位：都市發展局 發稿時間：115年11月3日11:20 臺南市長黃偉哲上任八年來，積極推動社會住宅政策，從無到有逐步擴大住宅供給，目前中央與市府共同推動社宅已達12,054戶，並有2,154戶陸續開辦招租。"}, {"title": "黃偉哲任內締盟成果展現城市外交新格局 促成多元實質交流", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8844847", "date": "2026-11-05", "unit": "臺南市政府", "category": "政策", "topic": "臺南市政府", "summary": "發稿單位:新聞及國際關係處 發稿時間:115年11月3日 台南市長黃偉哲上任以來，積極拓展與國際城市的夥伴關係，至今已經與9國、23個國際城市完成締盟，版圖橫跨亞洲、歐洲、美洲與加勒比海地區，更不乏京都、金澤、山口、紐奧良等國際知名大城，而最新一個締盟的英國大林肯郡，更創下台灣首個與英國城市締結為姊妹市的紀錄。"}, {"title": "地籍圖重測換狀免收費 多元申辦管道好便利", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8844824", "date": "2026-11-05", "unit": "臺南市政府", "category": "補助", "topic": "臺南市政府", "summary": "115年度地籍圖重測結果公告已於10月30日屆滿，後續將依規定辦理土地標示變更登記，並通知土地所有權人申請換發權狀。為讓民眾辦理換狀更便利，市府持續提供多元便民服務，除可至土地轄區地政事務所申辦外，亦可利用本市跨所申領、例假日換狀、下鄉換狀及預約換狀等服務，外縣市則有代收代寄服務，讓民眾依自身需求選擇適合的方式，不必為了換狀多次奔波，且換發權狀完全免費。"}, {"title": "南市府攜手企業推廣正確洗手衛教 黃偉哲籲從小養成良好衛生習慣", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8844856", "date": "2026-11-05", "unit": "臺南市政府", "category": "預算", "topic": "臺南市政府", "summary": "發稿單位：新聞及國際關係處 發稿時間：115年11月3日11:40 發稿人：葉泯萱 台南市政府今（3）日於東區崇學國小舉辦「洗手新日常，全民ALL IN」宣導活動，攜手饗賓文教基金會及耐斯集團推廣正確洗手觀念，並獲企業捐贈共1,000瓶抗菌洗手乳，投入校園及全民衛生教育。市長黃偉哲親自出席並頒發感謝狀，感謝企業發揮社會責任，以實際行動支持健康教育，共同守護學童與市民健康。"}, {"title": "臺東榮服處生日祝福再升級 簡訊傳心意、關懷更即時", "url": "https://www.taitung.gov.tw/News_Content.aspx?n=13370&s=150505", "date": "2026-11-05", "unit": "臺東縣政府", "category": "政策", "topic": "臺東縣政府", "summary": "臺東榮服處生日祝福再升級 簡訊傳心意、關懷更即時 新聞來源:臺東縣榮民服務處 為讓生日祝福更即時、更貼近服務對象使用習慣，臺東縣榮民服務處推動生日祝福簡訊服務，除傳遞生日祝福外，也可依時令及最新政策，適時搭配就醫、就學、就業、職訓、就養及退除給付等權益資訊，讓一則簡訊同時兼具祝福、關懷與服務資訊傳遞功能。"}, {"title": "「東稅玩稅不設限」11/5熱鬧登場！玩遊戲學租稅、集積分換好康 最高6,000元即享券等你拿！", "url": "https://www.taitung.gov.tw/News_Content.aspx?n=13370&s=150504", "date": "2026-11-05", "unit": "臺東縣政府", "category": "政策", "topic": "臺東縣政府", "summary": "年11月5日 「東稅玩稅不設限」11/5熱鬧登場！為推廣租稅教育及雲端發票使用觀念，臺東縣稅務局創新推出115年度「東稅玩稅不設限」線上租稅宣導活動，自今(5)日起至12月4日止，結合趣味遊戲、每日簽到、租稅問答及積分兌換等多元互動方式，邀請民眾透過輕鬆有趣的遊戲體驗學習租稅知識，還有機會獲得最高6,000元即享券，讓租稅學習變得更有趣、更有感！"}, {"title": "電氣因素火災頻傳！後勁分隊籲落實定期檢查臥室及客廳用電安全！", "url": "https://fdkc.kcg.gov.tw/News_Content.aspx?n=EF5454228AD21A21&sms=6BCA88A6633BE86E&s=BB449D2D0A858DB7", "date": "2026-11-05", "unit": "高雄市政府", "category": "綜合新聞", "topic": "高雄市政府", "summary": "新聞稿 - 資料更新時間：115-11-05 16:10 發布單位：消防局 近期本島氣候變化，時而高溫炎熱時而多雨潮濕，居家家電頻繁使用而導致「電氣因素」火災層出不窮。"}, {"title": "搶攻全球無人載具非紅供應鏈商機 深化臺美合作，協助臺南廠商進軍歐美市場", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13371&s=8845286", "date": "2026-11-05", "unit": "臺南市政府", "category": "綜合新聞", "topic": "臺南市政府", "summary": "全球地緣政治變化及國際供應鏈重組，帶動無人載具產業朝自主化、可信賴及多元布局發展，為臺灣企業切入國際市場創造新契機。首屆「2026臺灣海洋科技暨無人載具展（MATURE Taiwan）」於11月3日至5日在大臺南會展中心登場，匯集臺灣及海外共88個參展單位，其中包含17個美國相關單位。"}, {"title": "花蓮縣政府社會處18名同仁考取社會工作師 專業人才培育再傳捷報 持續打造優質社工服務環境", "url": "https://www.hl.gov.tw/News_Content.aspx?n=32725&sms=25832&s=233574", "date": "2026-11-05", "unit": "花蓮縣政府", "category": "政策", "topic": "花蓮縣政府", "summary": "花蓮縣政府社會處於115年第二次專門職業及技術人員高等考試社會工作師考試中傳來捷報，共有18名同仁順利考取社會工作師，展現本處同仁積極精進專業知能、持續自我成長的成果。考取同仁來自社工科、婦幼科、福利科、救助科及行政科，透過工作之餘持續投入考試準備，以實際行動展現對社會工作專業的熱忱與堅持，也為花蓮縣社會福利服務團隊增添專業能量。"}, {"title": "招標 - 116年度公務車租車(含駕駛、油料)(開口契約)", "url": "https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$M109&IDK=2&EXEC=D&DATA=77215&AP=$M109_HISTORY-0^$M109_PN-1", "date": "2026-11-05", "unit": "高雄市政府", "category": "標案", "topic": "高雄市政府", "summary": "[機關代碼]3.97.33 [機關名稱]高雄市政府文化局 [單位名稱]秘書室 [機關地址] 802高雄市苓雅區五福一路67號 [聯絡人] 黃馨儀 [聯絡電話] (07)2225136#8871 [傳真號碼] (07)2288874 [電子郵件信箱]hsin622513@gmail.com [標案案號…"}, {"title": "高市消防至那瑪夏民權國小舉辦消防體驗營宣導防災觀念", "url": "https://fdkc.kcg.gov.tw/News_Content.aspx?n=EF5454228AD21A21&sms=6BCA88A6633BE86E&s=957AC8B46B987B93", "date": "2026-11-05", "unit": "高雄市政府", "category": "政策", "topic": "高雄市政府", "summary": "新聞稿 - 資料更新時間：115-11-05 15:52 發布單位：消防局 為全面提升偏鄉學童的防火防災知識與緊急應變能力，高雄市政府消防局第六大隊第二中隊於今（5）日至高雄市那瑪夏區民權國民小學舉辦「消防體驗活動」。消防人員特別將消防車與救護車開進校園，透過精心設計的闖關遊戲、情境演練及實物實際操作，帶領全校師生深入認識居家與校園安全。"}, {"title": "招標 - 紅毛港文化園區海洋特色遊戲場設置案", "url": "https://khcc.kcg.gov.tw/rwd_home02.aspx?ID=$M109&IDK=2&EXEC=D&DATA=77214&AP=$M109_HISTORY-0^$M109_PN-1", "date": "2026-11-05", "unit": "高雄市政府", "category": "標案", "topic": "高雄市政府", "summary": "[機關代碼]3.97.33 [機關名稱]高雄市政府文化局 [單位名稱]文創發展中心 [機關地址] 802高雄市苓雅區五福一路67號 [聯絡人] 陳明億 [聯絡電話] (07)2225136#8341 [傳真號碼] (07)2288844 [電子郵件信箱]h939566@maul.khcc.gov.t…"}, {"title": "賣東西也會被騙！成功分局副分局長上警廣 揭露臉書假買家詐騙陷阱", "url": "https://www.taitung.gov.tw/News_Content.aspx?n=13370&s=150501", "date": "2026-11-05", "unit": "臺東縣政府", "category": "政策", "topic": "臺東縣政府", "summary": "年11月5日 賣東西也會被騙！成功分局副分局長上警廣 揭露臉書假買家詐騙陷阱 隨著社群媒體及網路交易日益普及，詐騙集團不僅假冒賣家騙取購物款項，更反過來偽裝成買家，利用交易流程設下陷阱。"}, {"title": "臺東警察分局處理轉運站前傷害案件相關說明", "url": "https://www.taitung.gov.tw/News_Content.aspx?n=13370&s=150500", "date": "2026-11-05", "unit": "臺東縣政府", "category": "綜合新聞", "topic": "臺東縣政府", "summary": "年11月05日 臺東警察分局處理轉運站前傷害案件相關說明 臺東警察分局於昨（4）日16時33分許接獲報案，稱臺東市鐵花路轉運站前有人持刀攻擊他人，警方獲報後立即派員趕赴現場，迅速將蔣姓（年約45歲）及洪姓（年約25歲）男子逮捕，並查扣木棒及西瓜刀各1把。"}, {"title": "布農文化輕旅行，樂齡共遊趣-馬蘭榮家安養堂長輩走出戶外樂融融", "url": "https://www.taitung.gov.tw/News_Content.aspx?n=13370&s=150496", "date": "2026-11-05", "unit": "臺東縣政府", "category": "綜合新聞", "topic": "臺東縣政府", "summary": "布農文化輕旅行，樂齡共遊趣-馬蘭榮家安養堂長輩走出戶外樂融融 新聞來源:退輔會馬蘭榮家 馬蘭榮家為了豐富安養堂長輩的精神生活，鼓勵住民走出房間、拓展生活經驗，特於今（5）日特別規劃辦理「布農文化輕旅行・樂齡共遊趣」健康促進活動。"}, {"title": "馬當部落交通安全宣導 警民攜手守護安心生活", "url": "https://www.taitung.gov.tw/News_Content.aspx?n=13370&s=150499", "date": "2026-11-05", "unit": "臺東縣政府", "category": "政策", "topic": "臺東縣政府", "summary": "年11月5日 馬當部落交通安全宣導 警民攜手守護安心生活 臺東縣警察局交通警察隊日前至馬當部落文健站，透過實際新聞及影片，向長者及社區居民宣導交通安全觀念，提升安全意識。在高齡駕駛用路安全方面，交通隊提醒，年長者在駕駛時應特別注意身體狀況與反應能力，若有視力或聽力退化，應避免獨自駕駛，以保障自身與他人安全。"}, {"title": "高雄重大兒虐死亡案件非六都最高 市府籲勿扭曲數據、應持續精進兒少保護機制", "url": "https://www.kcg.gov.tw/CityNews_Detail1.aspx?n=3A379BB94CA5F12D&ss=E9836A4D2A11440B", "date": "2026-11-05", "unit": "高雄市政府", "category": "政策", "topic": "高雄市政府", "summary": "市府嚴正呼籲，兒少保護攸關生命安全，不容以片面數據扭曲事實，更不能以數字爭論取代制度檢討、逃避責任。依據衛福部110年至114年統計，六都兒少保護服務人數則以新北市最多、臺中市第二、高雄市第三。另累計五年重大兒虐死亡人數，臺中市18人、新北市17人、高雄市15人，高雄並非六都最高，其中12人集中於113年，其餘四年每年均不超過1人。"}, {"title": "高雄市中正四路，於115年11月10日至14日進行路面改善工程，敬請行經車輛提前改道並注意行車安全", "url": "https://www.kcg.gov.tw/News_Content.aspx?n=F29A02A9D36C47F0&s=8AA766F626D197B0", "date": "2026-11-05", "unit": "高雄市政府", "category": "綜合新聞", "topic": "高雄市政府", "summary": "施工時段為晚間9時至隔日晨間6時。另為顧及工程品質，刨鋪後均依施工規範封閉養護6小時以上或溫度降低至50°C以下始開放通車，確保道路使用壽命及品質，如遇天候不佳，將順延一天進場施工。道工處表示，道路施工將避開市民上下班時段，以減少影響交通。施工期間將封閉工區車道並於現場安排義交，引導車輛通行及維持交通秩序，請駕駛車輛行經施工路段時，注意施工警示標誌並減速慢行。"}, {"title": "公告「變更高速公路永康交流道附近特定區計畫（第四次通盤檢討）（第十三階段）」（報部編號第十一案）都市計畫樁位公告圖、樁位圖及樁位坐標表、控制測量成果，並自民國115年11月5日起公告30天。", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=4977&s=8845318", "date": "2026-11-05", "unit": "臺南市政府", "category": "政策", "topic": "臺南市政府", "summary": "公告「變更高速公路永康交流道附近特定區計畫（第四次通盤檢討）（第十三階段）」（報部編號第十一案）都市計畫樁位公告圖、樁位圖及樁位坐標表、控制測量成果，並自民國115年11月5日起公告30天。 - 類別：公告 - 目：都發"}, {"title": "跨國公益攜手守護臺東 產經企業捐贈2輛巡迴醫療車", "url": "https://www.taitung.gov.tw/News_Content.aspx?n=13370&s=150495", "date": "2026-11-05", "unit": "臺東縣政府", "category": "政策", "topic": "臺東縣政府", "summary": "年11月5日 跨國公益攜手守護臺東 產經企業捐贈2輛巡迴醫療車 為提升基層醫療服務量能，台灣產經股份有限公司、產流通股份有限公司及台灣產健股份有限公司共同捐贈臺東縣2輛巡迴醫療車，展現企業關懷地方醫療及善盡社會責任的精神。"}];window.UPDATED="2026-11-15 03:42";window.CATS=["政策", "補助", "標案", "預算", "綜合新聞"];